describe('Sticky Header Navigation', () => {
  beforeEach(() => {
    cy.visit('/home');
  });

  it('should display sticky header and keep it visible when scrolling down', () => {
    // Verify header is visible initially
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('have.css', 'position', 'fixed');
    cy.get('[data-testid="header"]').should('have.css', 'top', '0px');

    // Verify header contains navigation links
    cy.get('[data-testid="nav-link-home"]').should('be.visible');
    cy.get('[data-testid="nav-link-about"]').should('be.visible');
    cy.get('[data-testid="nav-link-contact"]').should('be.visible');

    // Scroll down to trigger sticky behavior
    cy.scrollTo('bottom');

    // Verify header remains visible and fixed at the top
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('have.css', 'position', 'fixed');
    cy.get('[data-testid="header"]').should('have.css', 'top', '0px');

    // Verify header does not disappear when scrolling
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('not.have.css', 'display', 'none');

    // Verify navigation links are still accessible
    cy.get('[data-testid="nav-link-home"]').should('be.visible');
    cy.get('[data-testid="nav-link-about"]').should('be.visible');
  });

  it('should handle scrolling up and maintain sticky header visibility', () => {
    // Scroll down to trigger sticky header
    cy.scrollTo('bottom');
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('have.css', 'position', 'fixed');

    // Scroll back up
    cy.scrollTo('top');

    // Verify header remains sticky and visible
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="header"]').should('have.css', 'position', 'fixed');
    cy.get('[data-testid="header"]').should('have.css', 'top', '0px');

    // Verify header does not jump or flicker
    cy.get('[data-testid="header"]').should('not.have.css', 'opacity', '0');

    // Verify navigation links are still functional
    cy.get('[data-testid="nav-link-home"]').click();
    cy.url().should('include', '/home');
  });
});
